#!/bin/bash
# 3D 導演台 launcher — the executable inside "3D 導演台.app" (generated by scripts/make-mac-app.sh).
# Starts the local companion server if it is not running (rebuilding the web app first when the
# sources changed), then opens the app in its own Chrome window.
# The project folder: the folder this .app sits in when that is the project (so moving the whole
# project keeps the shortcut working), otherwise the path recorded when the app was generated.
APP_PARENT="$(cd "$(dirname "$0")/../../.." 2>/dev/null && pwd)"
if [ -f "$APP_PARENT/server/index.ts" ] && [ -f "$APP_PARENT/package.json" ]; then
  REPO="$APP_PARENT"
else
  REPO="__REPO__"
fi

# Script-based apps can be started under Rosetta on Apple silicon; node would then run as x86_64
# and the build tool's native (arm64) module would fail to load. Re-run natively.
if [ "$(uname -m)" = "x86_64" ] && [ "$(/usr/sbin/sysctl -n hw.optional.arm64 2>/dev/null)" = "1" ]; then
  exec /usr/bin/arch -arm64 /bin/bash "$0" "$@"
fi

PORT="${DIRECTOR_PORT:-5178}"
URL="http://127.0.0.1:${PORT}/"
# Logs live outside the project: macOS may refuse in-place writes to files in ~/Documents that
# were created under another app identity (e.g. an earlier copy of this launcher).
LOG="$HOME/Library/Logs/director3d-launcher.log"

alert() {
  /usr/bin/osascript -e "display alert \"3D 導演台\" message \"$1\" as critical" >/dev/null 2>&1
}

up() {
  [ "$(/usr/bin/curl -s -o /dev/null -m 1 -w '%{http_code}' "$URL")" = "200" ]
}

# Apps started from Finder get a minimal PATH; look for node where installers usually put it.
find_node() {
  export PATH="/usr/local/bin:/opt/homebrew/bin:$HOME/.volta/bin:$HOME/.local/bin:$PATH"
  for d in "$HOME"/.nvm/versions/node/*/bin; do
    [ -x "$d/node" ] && PATH="$d:$PATH"
  done
  command -v node >/dev/null 2>&1 && return 0
  local n
  n="$(/bin/zsh -lic 'command -v node' 2>/dev/null | tail -n 1)"
  if [ -x "$n" ]; then
    PATH="$(dirname "$n"):$PATH"
    return 0
  fi
  return 1
}

if [ ! -d "$REPO" ]; then
  alert "找不到專案資料夾：$REPO。如果搬動過專案，請在新位置執行 npm run mac-app 重新產生捷徑。"
  exit 1
fi
mkdir -p "$(dirname "$LOG")"
# Keep the log small.
if [ -f "$LOG" ] && [ "$(/usr/bin/stat -f %z "$LOG")" -gt 1048576 ]; then : >"$LOG"; fi

if ! up; then
  if ! find_node; then
    alert "找不到 Node.js（需要 22.18 以上）。請先安裝 Node.js。"
    exit 1
  fi
  cd "$REPO" || exit 1
  echo "[$(date '+%F %T')] starting server with $(command -v node) $(node -v) ($(uname -m))" >>"$LOG"
  # Rebuild when the web app sources are newer than the last build.
  if [ ! -f dist/index.html ] || [ -n "$(find src index.html AGENTS.md -type f ! -name .DS_Store -newer dist/index.html -print -quit 2>/dev/null)" ]; then
    echo "[$(date '+%F %T')] building the web app" >>"$LOG"
    if ! npm run build >>"$LOG" 2>&1; then
      alert "網頁建置失敗，詳情請看 ~/Library/Logs/director3d-launcher.log。"
      exit 1
    fi
  fi
  nohup node server/index.ts >>"$LOG" 2>&1 &
  disown
  for _ in $(seq 1 80); do
    up && break
    sleep 0.25
  done
  if ! up; then
    alert "伺服器沒有啟動，詳情請看 ~/Library/Logs/director3d-launcher.log。"
    exit 1
  fi
fi

echo "[$(date '+%F %T')] opening $URL (project: $REPO)" >>"$LOG"
if [ -d "/Applications/Google Chrome.app" ]; then
  # --app opens a clean window without tabs or address bar.
  /usr/bin/open -na "Google Chrome" --args --app="$URL"
else
  /usr/bin/open "$URL"
fi
